(() => {
  'use strict';
  const D=window.AI_ATLAS;
  if(!D){document.getElementById('main').innerHTML='<p class="load-error">The atlas could not load. Please refresh the page.</p>';return;}
  const $=s=>document.querySelector(s);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const topicMap=new Map(D.topics.map(t=>[t.id,t]));
  const facets=[{name:'Methods',full:'Computational methods',question:'What performs the computation?'},{name:'Learning',full:'Learning & adaptation',question:'How does behaviour improve?'},{name:'Model roles',full:'Model roles',question:'What does the model represent or produce?'},{name:'System patterns',full:'System patterns',question:'How are components combined?'},{name:'Engineering',full:'Cross-cutting engineering',question:'How is it efficient and dependable?'}];
  const icons={
    grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
    timeline:'<path d="M5 4v16M5 7h5M5 17h5M14 7h5M14 17h5"/><circle cx="12" cy="7" r="2"/><circle cx="12" cy="17" r="2"/>',
    route:'<circle cx="5" cy="6" r="2"/><circle cx="19" cy="18" r="2"/><path d="M7 6h9a4 4 0 0 1 0 8H8a4 4 0 0 0 0 8"/>',
    frontier:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',
    bookmark:'<path d="M6 4a1 1 0 0 1 1-1h10a1 1 0 0 1 1 1v17l-6-4-6 4Z"/>',
    search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
    close:'<path d="m6 6 12 12M6 18 18 6"/>',
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    external:'<path d="M8 5h11v11M19 5 5 19"/>',
    chevron:'<path d="m9 6 6 6-6 6"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    circlecheck:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',
    book:'<path d="M12 5v16M3 4h5a4 4 0 0 1 4 2 4 4 0 0 1 4-2h5v15h-5a4 4 0 0 0-4 2 4 4 0 0 0-4-2H3Z"/>',
    file:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9Z"/><path d="M14 3v6h6M8 13h8M8 17h5"/>',
    bulb:'<path d="M9 18h6M10 22h4M9 15c0-2-3-3-3-6a6 6 0 0 1 12 0c0 3-3 4-3 6Z"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
    back:'<path d="M19 12H5m6 6-6-6 6-6"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.5"/>'
  };
  function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;}
  function injectIcons(){document.querySelectorAll('[data-icon]').forEach(n=>{n.innerHTML=icon(n.dataset.icon);});}
  let state={saved:[],read:[],journey:null};
  try{const v=JSON.parse(localStorage.getItem('ai-atlas:v1')||'{}');state={saved:Array.isArray(v.saved)?v.saved.filter(id=>topicMap.has(id)):[],read:Array.isArray(v.read)?v.read.filter(id=>topicMap.has(id)):[],journey:typeof v.journey==='string'?v.journey:null};}catch{}
  function persist(){try{localStorage.setItem('ai-atlas:v1',JSON.stringify(state));}catch{toast('Saved for this session. Browser storage is unavailable.');}updateCounts();}
  function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2300);}
  function updateCounts(){$('#saved-count').textContent=state.saved.length;}
  const nav=[['explore','grid','Explore techniques'],['history','timeline','Evolution & history'],['journeys','route','Learning journeys'],['frontiers','frontier','Research frontier']];
  $('#navigation').innerHTML=nav.map(([id,i,l])=>`<a class="nav-item" data-nav="${id}" href="#${id}">${icon(i)}${l}</a>`).join('');
  $('#mobile-menu').innerHTML=icon('menu');injectIcons();updateCounts();
  function availability(url){
    const a=D.linkChecks?.[url];if(!a)return 'HTTP availability not checked';
    const labels={reachable:'HTTP '+a.http_status,not_found:'HTTP '+a.http_status+' · not found',rate_limited:'HTTP 429 · rate limited',access_restricted:'Access restricted'+(a.http_status?' · HTTP '+a.http_status:''),network_error:'Network check inconclusive',http_error:'HTTP '+a.http_status+' · unresolved',not_checked:'Not checked'};
    return (labels[a.state]||'Unresolved')+' · '+a.checked_at.slice(0,10);
  }
  function refLink(r){let domain='Reference';try{domain=new URL(r.url).hostname.replace(/^www\./,'');}catch{}return `<a class="reference-link" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer"><span class="ref-icon">${icon('file')}</span><span class="ref-text"><strong>${esc(r.title)}</strong><small>${esc(domain)} · ${esc(r.kind||'reference')}${r.year?' · '+esc(r.year):''}</small><small class="reference-status" title="Automated availability check. A successful HTTP response does not verify the source’s content or scientific claims.">${esc(availability(r.url))}</small></span><span class="arrow" aria-hidden="true">↗</span></a>`;}

  function related(ids){return `<div class="related-links">${ids.filter(id=>topicMap.has(id)).map(id=>`<a class="related-link" href="#explore/${id}">${esc(topicMap.get(id).name)}</a>`).join('')}</div>`;}
  function shortName(t){const names={'topic-022':'Transformers & attention','topic-003':'Ontologies & knowledge graphs','topic-063':'Retrieval-augmented generation','topic-074':'Neural + symbolic reasoning','topic-073':'Metacognitive monitoring & control','topic-051':'Test-time learning & memory'};return names[t.id]||t.name;}
  function glossaryList(){return `<dl class="glossary-list">${D.glossary.map(g=>`<div><dt>${esc(g.term)}</dt><dd>${esc(g.definition)}</dd></div>`).join('')}</dl>`;}
  function glossaryCard(){return `<section class="glossary-card" aria-labelledby="first-words"><div class="eyebrow">BEFORE YOU BEGIN</div><h2 id="first-words">Six words to start with</h2><p>You will meet these words throughout the Atlas. Open “Six key words” beside any plain-language heading to revisit them.</p>${glossaryList()}</section>`;}
  document.body.insertAdjacentHTML('beforeend',`<dialog id="glossary-dialog" class="glossary-dialog" aria-labelledby="glossary-title"><div class="dialog-title"><span class="eyebrow">A QUICK REFERENCE</span><button class="icon-button" data-action="close-glossary" aria-label="Close glossary">${icon('close')}</button></div><h2 id="glossary-title">Six words to start with</h2>${glossaryList()}</dialog>`);
  function topicDetail(id){
    const t=topicMap.get(id);if(!t)return '';
    const journey=D.journeys.find(j=>j.id===state.journey),step=journey?.topics.indexOf(id)??-1,next=step>=0?journey.topics[step+1]:null;
    const category=t.path[t.path.length-1].replace(/ —.*$/,'').replace(/^[1-5] · /,'');
    const mins=Math.max(1,Math.ceil([t.plain,t.detail,t.context,t.example,t.limitation].join(' ').split(/\s+/).length/220));
    return `<article class="topic-detail" aria-label="${esc(t.name)} topic guide"><div class="topic-detail-header"><div class="topic-detail-top"><span class="badge">${esc(category)}</span><button class="icon-button save-button ${state.saved.includes(id)?'saved':''}" data-action="save" data-id="${id}" aria-label="${state.saved.includes(id)?'Remove from':'Add to'} reading list" aria-pressed="${state.saved.includes(id)}">${icon('bookmark')}</button></div><h2>${esc(shortName(t))}</h2><section class="plain-intro" aria-labelledby="plain-heading"><div class="plain-intro-heading"><h3 id="plain-heading">In plain words</h3><a class="glossary-link" href="#journeys/foundations" data-action="open-glossary" aria-haspopup="dialog">Six key words</a></div><p>${esc(t.plain)}</p></section></div><div class="detail-body"><section class="detail-section"><h3>THE IDEA</h3><p class="topic-lead">${esc(t.detail)}</p><p>${esc(t.context)}</p></section><section class="detail-section example-box"><h3>${icon('bulb')} IN PRACTICE · ILLUSTRATIVE EXAMPLE</h3><p>${esc(t.example||'')}</p></section><section class="detail-section limitation-box"><h3>WHAT TO KEEP IN MIND</h3><p>${esc(t.limitation||'')}</p></section><section class="detail-section"><h3>GO TO THE SOURCE</h3>${(t.refs||[]).map(refLink).join('')}</section><section class="detail-section"><h3>CONNECTED IDEAS</h3>${related(t.related||[])}</section></div><div class="detail-actions"><button class="read-button ${state.read.includes(id)?'done':''}" data-action="read" data-id="${id}" aria-pressed="${state.read.includes(id)}">${icon('circlecheck')}${state.read.includes(id)?'Read':'Mark as read'}</button>${next?`<a class="next-link" href="#explore/${next}">Next in journey →</a>`:`<span class="detail-time">${mins} min read + references</span>`}</div></article>`;
  }
  function heroArt(){return `<div class="hero-art"><svg viewBox="0 0 460 330" role="img" aria-label="Five complementary facets: methods, learning, model roles, systems and engineering"><defs><pattern id="hero-grid" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".65" fill="#aebea1" opacity=".5"/></pattern><radialGradient id="node-grad"><stop stop-color="#f2f6e7"/><stop offset="1" stop-color="#d5e2bf"/></radialGradient></defs><rect width="460" height="330" fill="url(#hero-grid)" opacity=".65"/><g fill="none" stroke="#bdcdb0" stroke-width=".8"><ellipse cx="238" cy="166" rx="140" ry="86" transform="rotate(-28 238 166)"/><ellipse cx="238" cy="166" rx="147" ry="66" transform="rotate(40 238 166)"/><ellipse cx="238" cy="166" rx="69" ry="144" transform="rotate(23 238 166)"/><path d="M132 94 238 166 349 110M238 166 312 265M238 166 115 235M238 166 254 35" stroke-dasharray="3 4"/></g><circle cx="238" cy="166" r="49" fill="url(#node-grad)" stroke="#b5c69e" stroke-width=".7"/><circle cx="238" cy="166" r="38" fill="none" stroke="#b5c69e" stroke-width=".6"/><text x="238" y="180" text-anchor="middle" fill="#4d6d35" font-family="Georgia,serif" font-size="39" font-style="italic">ai</text>${[[132,94,'Methods',1],[349,110,'Learning',2],[312,265,'Model roles',3],[115,235,'Systems',4],[254,35,'Engineering',5]].map(([x,y,n,f])=>`<a href="#explore?facet=${f}" aria-label="Explore ${n}"><circle cx="${x}" cy="${y}" r="7" fill="#e5edda" stroke="#8fae6f"/><circle cx="${x}" cy="${y}" r="2" fill="#7e9b60"/><rect x="${x-40}" y="${y+14}" width="80" height="23" rx="11" fill="#f4f7ed" stroke="#dde6d1"/><text x="${x}" y="${y+29}" text-anchor="middle" fill="#7b9067" font-family="Arial,sans-serif" font-size="9">${n}</text></a>`).join('')}<g fill="#a3b68c"><circle cx="316" cy="54" r="2"/><circle cx="382" cy="202" r="2"/><circle cx="184" cy="295" r="2"/><circle cx="90" cy="159" r="2"/></g></svg><span class="art-caption">DISTINCT FACETS. SHARED POSSIBILITIES.</span></div>`;}
  function treeHtml(node,selected,depth=0){if(!node.children){const t=topicMap.get(node.id);return `<button class="topic-row ${node.id===selected?'selected':''}" data-action="select-topic" data-id="${node.id}" ${node.id===selected?'aria-current="true"':''}>${esc(t.name)}${state.read.includes(node.id)?'<span class="check" aria-label="Read">✓</span>':'<span class="topic-arrow" aria-hidden="true">↗</span>'}</button>`;}const has=(n)=>n.id===selected||(n.children||[]).some(has);const count=(n)=>n.children?n.children.reduce((v,c)=>v+count(c),0):1;return `<details class="tree-node" ${has(node)?'open':''}><summary><span class="chev">${icon('chevron')}</span>${esc(node.name)}<span class="branch-num">${count(node)}</span></summary><div class="tree-children">${node.children.map(n=>treeHtml(n,selected,depth+1)).join('')}</div></details>`;}
  let currentTopic='topic-022', currentFacet=1;
  function renderExplore(id,facetArg){
    const valid=topicMap.has(id);currentFacet=valid?topicMap.get(id).facet:(facetArg>=1&&facetArg<=5?facetArg:1);currentTopic=valid?id:(currentFacet===1?'topic-022':D.topics.find(t=>t.facet===currentFacet).id);
    return `<section class="hero"><div class="hero-copy"><div class="hero-kicker"><span></span> THE IDEAS BEHIND INTELLIGENCE</div><h1>Intelligence,<br><em>unfolded.</em></h1><p class="hero-description">Explore the methods, models and ideas shaping AI. Understand what they do, where they came from, and how they fit together.</p><div class="hero-meta"><span><strong>${D.topics.length}</strong> technique guides</span><span><strong>5</strong> complementary facets</span><span><strong>80+</strong> years of ideas</span></div></div>${heroArt()}</section><section id="landscape"><div class="section-heading"><div><h2>Explore the landscape</h2><p>Different lenses. One connected field.</p></div><a class="inline-link" href="#figures/tree">Open the full tree ${icon('external')}</a></div><div class="facets" role="tablist" aria-label="AI classification facets">${facets.map((f,i)=>`<button class="facet-tab ${i+1===currentFacet?'active':''}" role="tab" aria-selected="${i+1===currentFacet}" data-action="facet" data-facet="${i+1}">${f.name}<span>${D.topics.filter(t=>t.facet===i+1).length}</span></button>`).join('')}</div><div class="explorer"><div class="tree-panel"><div class="tree-tools"><span class="small-label">${esc(facets[currentFacet-1].question)}</span><button class="subtle-button" data-action="expand-tree">Expand all</button></div><div id="native-tree">${D.tree[currentFacet-1].children.map(n=>treeHtml(n,currentTopic)).join('')}</div></div><div id="topic-detail-slot">${topicDetail(currentTopic)}</div></div></section><section class="discovery-strip"><div class="discovery-item"><div class="small-art">${icon('timeline')}</div><div><h3>Every idea has a history.</h3><p>Trace the connections from early logic to today's hybrid systems.</p><a class="inline-link" href="#history">Follow the timeline ${icon('arrow')}</a></div></div><div class="discovery-item"><div class="small-art">${icon('route')}</div><div><h3>A little direction helps.</h3><p>Build your understanding with a carefully sequenced learning journey.</p><a class="inline-link" href="#journeys">Choose a learning path ${icon('arrow')}</a></div></div></section>`;
  }
  function heading(kicker,title,desc){return `<header class="page-heading"><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></header>`;}
  let historyView='figure';
  function historyPage(){return `${heading('THE EVOLUTION OF IDEAS','Progress is a<br><em>connected story.</em>','AI has developed through parallel traditions, revivals and unexpected combinations. Follow selected milestones and see how earlier ideas inform today’s systems.')}<div class="view-toggle" role="group" aria-label="History view"><button class="${historyView==='figure'?'active':''}" data-action="history-view" data-view="figure" aria-pressed="${historyView==='figure'}">Interactive figure</button><button class="${historyView==='story'?'active':''}" data-action="history-view" data-view="story" aria-pressed="${historyView==='story'}">Read the milestones</button></div>${historyView==='figure'?`<div class="figure-frame"><iframe src="figures/history.html" title="Interactive AI evolution timeline" data-autosize loading="eager"></iframe></div><p class="figure-caption">An original AI Atlas figure with interactive connections, updated from the shared milestone data. Dates identify selected milestones, not necessarily first inventions. Period bands are not a linear time scale. Dashed arrows indicate undated possibilities.</p>`:storyTimeline()}`;}
  function storyTimeline(){return `<div class="timeline-story">${D.history.eras.map((era,i)=>`<section class="story-era"><h2>${esc(era)}</h2><div class="story-grid">${D.history.nodes.filter(n=>n.row===i).map(n=>`<article class="story-card ${n.future?'future':''}"><h3>${esc(n.label)}</h3><div class="date">${esc(n.date)}</div><p>${esc(n.note)}</p>${n.refs.map((r,k)=>`<a href="${esc(D.history.sources[r])}" target="_blank" rel="noopener noreferrer" title="${esc(availability(D.history.sources[r]))}">Source ${k+1} ↗</a>`).join('')}</article>`).join('')}</div></section>`).join('')}</div>`;}
  function figurePage(){return `<a class="back-link" href="#explore">${icon('back')} Back to the learning explorer</a>${heading('THE FACETED CLASSIFICATION','The whole field.<br><em>Five ways to see it.</em>','Expand any branch and select a technique. Start with the plain-language introduction, then explore the explanation, example, limitations and linked research or documentation.')}<div class="figure-frame tree-frame"><iframe src="figures/tree.html" title="Faceted classification tree with expanded learning notes" data-autosize loading="eager"></iframe></div><p class="figure-caption">These branches describe complementary dimensions. For example, a model can be a transformer, trained with self-supervision, specialised for language, and used inside an agent with retrieval.</p>`;}
  function journeysPage(){return `${heading('GUIDED LEARNING','Find your<br><em>way into AI.</em>','Start with the question that matters to you. Each journey connects a small set of techniques in a deliberate order. Take it at your own pace.')}<div class="journey-grid">${D.journeys.map((j,i)=>{const done=j.topics.filter(id=>state.read.includes(id)).length;return `<article class="journey-card"><span class="journey-number">JOURNEY 0${i+1}</span><h2>${esc(j.title)}</h2><p>${esc(j.description)}</p><div class="journey-meta"><span>${j.topics.length} topics</span><span>${done} of ${j.topics.length} read</span></div><div class="progress-track" role="progressbar" aria-label="Reading progress for ${esc(j.title)}" aria-valuemin="0" aria-valuemax="${j.topics.length}" aria-valuenow="${done}"><span style="width:${done/j.topics.length*100}%"></span></div><a class="primary-button" href="#journeys/${j.id}">Explore journey ${icon('arrow')}</a></article>`;}).join('')}</div><div class="callout">${icon('info')}<p>Progress reflects the topics you mark as read, not a test of understanding. Bookmarks and progress are stored in this browser so you can pick up where you left off.</p></div>`;}
  function journeyPage(id){const j=D.journeys.find(x=>x.id===id);if(!j)return journeysPage();return `<a class="back-link" href="#journeys">${icon('back')} All learning journeys</a>${heading('A GUIDED LEARNING JOURNEY',esc(j.title),esc(j.description))}${id==='foundations'?glossaryCard():''}<button class="primary-button" data-action="start-journey" data-id="${id}">${j.topics.some(x=>state.read.includes(x))?'Continue':'Start'} this journey ${icon('arrow')}</button><ol class="journey-list">${j.topics.map((id,i)=>{const t=topicMap.get(id);return `<li><a class="journey-step" href="#explore/${id}" data-journey="${j.id}"><span class="step-number ${state.read.includes(id)?'done':''}">${state.read.includes(id)?'✓':String(i+1).padStart(2,'0')}</span><div><h3>${esc(t.name)}</h3><p>${esc(t.plain)}</p></div><span aria-hidden="true">↗</span></a></li>`;}).join('')}</ol>`;}
  function frontierPage(){return `${heading('AT THE RESEARCH FRONTIER','What is taking<br><em>shape next?</em>','New directions often recombine familiar ideas. Explore what has been demonstrated, what might follow, and the important questions still open.')}<div class="frontier-grid">${D.frontiers.map(f=>`<article class="frontier-card"><span class="badge research">${esc(f.status)}</span><h2>${esc(f.title)}</h2><p>${esc(f.demonstrated)}</p><h3>A PLAUSIBLE DIRECTION</h3><p>${esc(f.direction)}</p><p class="caution">${esc(f.caution)}</p>${f.refs.map(refLink).join('')}${related(f.topics)}</article>`).join('')}</div><div class="callout">${icon('info')}<p>These are research directions, not delivery forecasts. Strong performance on a benchmark does not establish dependable performance in a new operating environment.</p></div>`;}
  function savedPage(){const list=state.saved.map(id=>topicMap.get(id)).filter(Boolean);return `${heading('YOUR READING LIST','Keep the ideas<br><em>worth returning to.</em>','Save techniques as you explore. Your reading list and progress stay in this browser.')}<div class="reading-toolbar"><span>${list.length} saved ${list.length===1?'technique':'techniques'} · ${state.read.length} ${state.read.length===1?'topic':'topics'} marked as read</span><a class="inline-link" href="#explore">Explore the atlas →</a></div>${list.length?`<div class="saved-list">${list.map(t=>`<article class="saved-card"><div class="saved-card-top"><span class="badge">${esc(facets[t.facet-1].name)}</span><button class="icon-button" data-action="save" data-id="${t.id}" aria-label="Remove ${esc(t.name)} from reading list">${icon('close')}</button></div><h2>${esc(shortName(t))}</h2><p>${esc(t.plain)}</p><a class="inline-link" href="#explore/${t.id}">${state.read.includes(t.id)?'Revisit technique':'Read the guide'} ${icon('arrow')}</a></article>`).join('')}</div>`:`<div class="empty-state">${icon('bookmark')}<h2>Your next discovery belongs here.</h2><p>Use the bookmark on any technique guide to build a reading list around your interests.</p><a class="primary-button" href="#explore">Explore techniques ${icon('arrow')}</a></div>`}`;}
  let lastPage=null, revealTopic=false;
  function route(){
    const raw=location.hash.slice(1)||'explore', [path,query='']=raw.split('?'),[page,id]=path.split('/');const params=new URLSearchParams(query);let html;
    if(page==='history')html=historyPage();else if(page==='figures')html=figurePage();else if(page==='journeys')html=id?journeyPage(id):journeysPage();else if(page==='frontiers')html=frontierPage();else if(page==='saved')html=savedPage();else html=renderExplore(id,Number(params.get('facet')));
    $('#main').innerHTML=html;
    document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===(page==='figures'?'explore':nav.some(n=>n[0]===page)||page==='saved'?page:'explore');el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
    const label={explore:'EXPLORE',history:'HISTORY',journeys:'LEARNING JOURNEYS',frontiers:'RESEARCH FRONTIER',saved:'READING LIST',figures:'CLASSIFICATION FIGURE'}[page]||'EXPLORE';$('#current-section').textContent=label;document.title=`${label.charAt(0)+label.slice(1).toLowerCase()} — AI Atlas`;
    if(lastPage!==page)window.scrollTo({top:0,behavior:'instant'});
    lastPage=page;setupFrames();closeMobile();
    if(revealTopic && page==='explore') {$('#topic-detail-slot')?.scrollIntoView({block:'start',behavior:'instant'});revealTopic=false;}
  }
  function setupFrames(){document.querySelectorAll('iframe[data-autosize]').forEach(frame=>{
    frame.addEventListener('load',()=>{try{const doc=frame.contentDocument,root=doc?.querySelector('[data-figure-root]');if(!root)return;const resize=()=>{const h=Math.ceil(root.getBoundingClientRect().height+32);if(h>100&&Math.abs(frame.getBoundingClientRect().height-h)>3)frame.style.height=h+'px';};const observer=new ResizeObserver(()=>{if(!frame.isConnected){observer.disconnect();return;}resize();});observer.observe(root);resize();}catch{}});
  });}
  function selectTopic(id){if(!topicMap.has(id))return;const y=window.scrollY;location.hash='explore/'+id;requestAnimationFrame(()=>{if(innerWidth<=650)$('#topic-detail-slot')?.scrollIntoView({block:'start',behavior:'smooth'});else window.scrollTo({top:y,behavior:'instant'});});}
  function closeMobile(){$('#sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');}
  function search(q=''){const term=q.trim().toLowerCase();const result=(term?D.topics.filter(t=>[t.name,t.plain,t.detail,t.context,t.example,...t.path].join(' ').toLowerCase().includes(term)):D.topics.filter(t=>['topic-022','topic-003','topic-063','topic-066','topic-073','topic-060'].includes(t.id))).slice(0,20);$('#search-results').innerHTML=result.length?result.map(t=>`<a class="search-result" href="#explore/${t.id}" data-action="search-result"><strong>${esc(t.name)}</strong><p class="search-summary">${esc(t.plain)}</p><small>${esc(facets[t.facet-1].full)} · ${esc(t.path[t.path.length-1])}</small></a>`).join(''):`<p class="no-search">No techniques match “${esc(q)}”. Try “learning”, “planning”, or “uncertainty”.</p>`;}
  function openSearch(){search('');$('#global-query').value='';$('#search-dialog').showModal();$('#global-query').focus();}
  $('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});});
  $('#search-open').addEventListener('click',openSearch);$('#global-query').addEventListener('input',e=>search(e.target.value));
  $('#mobile-menu').addEventListener('click',()=>{const on=$('#sidebar').classList.toggle('open');$('#mobile-menu').setAttribute('aria-expanded',String(on));});
  document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if(e.key==='Escape')closeMobile();});
  document.addEventListener('click',e=>{
    if(e.target.closest('a[href^="#explore/"]')) revealTopic=true;
    const journey=e.target.closest('[data-journey]');if(journey){state.journey=journey.dataset.journey;persist();}
    const b=e.target.closest('[data-action]');if(!b){if(!e.target.closest('#sidebar,#mobile-menu'))closeMobile();return;}
    const a=b.dataset.action,id=b.dataset.id;
    if(a==='select-topic')selectTopic(id);
    if(a==='facet'){location.hash='explore?facet='+b.dataset.facet;}
    if(a==='save'){const was=state.saved.includes(id);state.saved=was?state.saved.filter(x=>x!==id):[...state.saved,id];persist();if(location.hash.startsWith('#saved'))route();else {const slot=$('#topic-detail-slot');if(slot)slot.innerHTML=topicDetail(currentTopic);}toast(was?'Removed from your reading list':'Saved to your reading list');}
    if(a==='read'){const was=state.read.includes(id);state.read=was?state.read.filter(x=>x!==id):[...state.read,id];persist();$('#topic-detail-slot').innerHTML=topicDetail(id);$('#native-tree').innerHTML=D.tree[currentFacet-1].children.map(n=>treeHtml(n,id)).join('');toast(was?'Marked as unread':'Progress saved. Keep exploring.');}
    if(a==='expand-tree'){const ds=[...document.querySelectorAll('#native-tree details')];const open=ds.some(d=>!d.open);ds.forEach(d=>d.open=open);b.textContent=open?'Collapse all':'Expand all';}
    if(a==='history-view'){historyView=b.dataset.view;route();}
    if(a==='start-journey'){const j=D.journeys.find(j=>j.id===id);if(j){state.journey=id;revealTopic=true;persist();location.hash='explore/'+(j.topics.find(t=>!state.read.includes(t))||j.topics[0]);}}
    if(a==='open-glossary'){e.preventDefault();$('#glossary-dialog').showModal();}if(a==='close-glossary')$('#glossary-dialog').close();
    if(a==='about')$('#about-dialog').showModal();if(a==='close-about')$('#about-dialog').close();
    if(a==='close-search'||a==='search-result')$('#search-dialog').close();
  });
  ['search-dialog','about-dialog','glossary-dialog'].forEach(id=>$('#'+id).addEventListener('click',e=>{if(e.target.id===id){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}}));
  const meta=D.meta;
  $('#atlas-credits').textContent=meta.production;
  $('#atlas-licensing').textContent=meta.licensing;
  $('#atlas-version').textContent='v'+meta.version+' · Snapshot '+meta.snapshot_date;
  $('#atlas-maintainer').textContent='AI ATLAS · Maintained by '+meta.maintainer;
  const audit=D.linkAudit;
  $('#atlas-link-audit').textContent=audit?'HTTP audit completed '+audit.finished_at.replace('T',' ').replace('+00:00',' UTC')+'. '+Object.entries(audit.counts).map(([k,v])=>v+' '+k.replaceAll('_',' ')).join(' · ')+'.':'No HTTP audit is included in this build.';
  window.addEventListener('hashchange',route);route();
})();
